import React, { useState } from 'react'; 
import { useNavigate } from 'react-router-dom'; 
import { useAuth } from '../contexts/AuthContext';

export default function LoginPage() { 
    const [username, setUsername] = useState(''); 
    const [password, setPassword] = useState(''); 
    const [error, setError] = useState(null); 
    const navigate = useNavigate(); 
    const { login } = useAuth();
    const handleSubmit = async (e) => { 
        e.preventDefault(); 
        const ok = await login(username, password); 
        if (ok) {('/dashboard', { replace: true }); } 
            else { setError('Неправильные учетные данные'); } 
        };

    return ( 
        <div className="login-page"> 
            <h2>Авторизация</h2> 
                <form onSubmit={handleSubmit}> 
            <div> 
                <label>Логин</label> 
                <input value={username} onChange={(e) => 
                    setUsername(e.target.value)} placeholder="Введите логин" /> 
            </div> 
            <div> 
                <label>Пароль</label> <input type="password" value={password} onChange={(e) => 
                    setPassword(e.target.value)} placeholder="Введите пароль" /> 
            </div> 
            {error && <div className="error" style={{color: 'red'}}>{error}</div>} 
            <button type="submit">Войти</button> </form> </div> 
        ); 
    }
